{
  "format": "complete-a-commitment/1",
  "module": {
    "id": "street-team-operating-review",
    "version": "1.0.0",
    "title": "Review a street-team deployment",
    "question": "Which complete street-team deployments fit tonight\u2019s staffing, timing, access and spending requirements?",
    "description": "Compare complete static deployments for one fictional venue and event. All passing options remain visible; Sam makes the choice. Customer response and additional guest thresholds do not establish marketing effectiveness.",
    "template": {
      "id": "complete-a-commitment",
      "version": 1
    },
    "units": {
      "time": "minute",
      "timeOrigin": "00:00 on the recorded operating date; one same-day local clock",
      "money": "USD cent",
      "count": "qualified staff member"
    },
    "assumptions": [
      "All names, records, event details, quantities and financial amounts are fictional teaching inputs.",
      "One complete deployment is fixed before departure. The options are mutually exclusive; no split teams, staggered shifts, adaptive interventions or additional promotions are generated.",
      "Every staff member counted is qualified for the simplified inside work, and remains available throughout the entire declared promotion absence. Individual stations, breaks, travel staffing and unrelated bookings require a richer module.",
      "The reviewed available count is qualified staff minus unavailable staff. The minimum inside count applies throughout the whole absence, not only at dispatch.",
      "Each option quote is its complete future incremental cash expense. Sunk and already committed costs are excluded. Separate existing-customer discount loss is an economic consequence, not an additional cash deployment charge.",
      "Access and spending registries are stipulated complete. Missing, false, expired, differently scoped or unsourced records confer no permission. Sam\u2019s final choice and specific deployment authorization are recorded separately by the workflow.",
      "All timing uses one same-day minute origin. Event exit and the customer journey are conditional planning declarations, not actual attendance or evidence that any guest accepted an offer.",
      "No forecast of genuinely additional guests, probability of response, expected profit or profit-maximizing ranking is supplied. Hold is an available baseline and is not declared best because it costs nothing."
    ],
    "inputs": {
      "parameters": {
        "venueId": {
          "type": "string"
        },
        "eventId": {
          "type": "string"
        },
        "operatingDate": {
          "type": "string"
        },
        "actorId": {
          "type": "string"
        },
        "qualifiedStaff": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "unavailableStaff": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "minimumInside": {
          "type": "integer",
          "unit": "count",
          "minimum": 0
        },
        "reviewMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "dispatchMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "promotionStartMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "eventExitMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "contactEndMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "staffReturnMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "customerJourneyMinutes": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "latestArrivalMinute": {
          "type": "integer",
          "unit": "time",
          "minimum": 0,
          "maximum": 1439
        },
        "expenseLimitMinor": {
          "type": "integer",
          "unit": "money",
          "minimum": 0
        }
      },
      "tables": {
        "options": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "label": {
              "type": "string"
            },
            "promoters": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            },
            "expenseMinor": {
              "type": "integer",
              "unit": "money",
              "minimum": 0
            }
          }
        },
        "scenarios": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            }
          }
        },
        "access": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "venueId": {
              "type": "string"
            },
            "eventId": {
              "type": "string"
            },
            "operatingDate": {
              "type": "string"
            },
            "activity": {
              "type": "string"
            },
            "granted": {
              "type": "boolean"
            },
            "validFromMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "validThroughMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "source": {
              "type": "string"
            }
          }
        },
        "spending": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "venueId": {
              "type": "string"
            },
            "operatingDate": {
              "type": "string"
            },
            "actorId": {
              "type": "string"
            },
            "ceilingMinor": {
              "type": "integer",
              "unit": "money",
              "minimum": 0
            },
            "validFromMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "validThroughMinute": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "source": {
              "type": "string"
            }
          }
        },
        "resources": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "capacity": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        },
        "bookings": {
          "key": [
            "id"
          ],
          "columns": {
            "id": {
              "type": "string"
            },
            "resource": {
              "type": "string"
            },
            "start": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "end": {
              "type": "integer",
              "unit": "time",
              "minimum": 0,
              "maximum": 1439
            },
            "amount": {
              "type": "integer",
              "unit": "count",
              "minimum": 0
            }
          }
        }
      }
    },
    "choices": [
      {
        "id": "deployment",
        "domain": {
          "values": [
            "hold",
            "small-standard",
            "large-standard",
            "large-discount"
          ]
        }
      }
    ],
    "scenarioDomain": {
      "table": "scenarios"
    },
    "lookupCoverage": [
      {
        "table": "options",
        "keys": {
          "id": {
            "domain": {
              "values": [
                "hold",
                "small-standard",
                "large-standard",
                "large-discount"
              ]
            }
          }
        }
      }
    ],
    "derived": [
      {
        "id": "promoters",
        "type": "integer",
        "unit": "count",
        "expr": {
          "op": "lookup",
          "table": "options",
          "where": {
            "id": {
              "ref": "choice.deployment"
            }
          },
          "column": "promoters"
        }
      },
      {
        "id": "insideStaff",
        "type": "integer",
        "unit": "count",
        "expr": {
          "op": "sub",
          "args": [
            {
              "op": "sub",
              "args": [
                {
                  "ref": "parameter.qualifiedStaff"
                },
                {
                  "ref": "parameter.unavailableStaff"
                }
              ]
            },
            {
              "ref": "derived.promoters"
            }
          ]
        }
      },
      {
        "id": "customerArrivalMinute",
        "type": "integer",
        "unit": "time",
        "expr": {
          "op": "add",
          "args": [
            {
              "ref": "parameter.eventExitMinute"
            },
            {
              "ref": "parameter.customerJourneyMinutes"
            }
          ]
        }
      }
    ],
    "activities": [],
    "resources": {
      "definitions": {
        "table": "resources",
        "idColumn": "id",
        "capacityColumn": "capacity"
      },
      "bookings": {
        "table": "bookings",
        "resourceColumn": "resource",
        "startColumn": "start",
        "endColumn": "end",
        "amountColumn": "amount"
      }
    },
    "requirements": [
      {
        "id": "SUFFICIENCY",
        "label": "Inside staffing",
        "meaning": "Retain enough qualified staff for the complete absence.",
        "waivable": false
      },
      {
        "id": "COVERAGE",
        "label": "Complete deployment",
        "meaning": "Preserve the authored finite complete option structures.",
        "waivable": false
      },
      {
        "id": "ACCESS",
        "label": "Recorded access and delegated spending",
        "meaning": "Require the exact current operating permissions.",
        "waivable": false
      },
      {
        "id": "TIME",
        "label": "Useful contact and arrival",
        "meaning": "Allow review, dispatch, contact, return and useful conditional customer arrival.",
        "waivable": false
      },
      {
        "id": "COST",
        "label": "Incremental spending ceiling",
        "meaning": "Keep the complete future deployment charge within the recorded limit.",
        "waivable": false
      }
    ],
    "constraints": [
      {
        "id": "published-option-structure",
        "requirement": "COVERAGE",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "hold"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 0
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "expenseMinor"
                    },
                    {
                      "literal": 0
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "small-standard"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 1
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "large-standard"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 2
                    }
                  ]
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "eq",
                  "args": [
                    {
                      "ref": "choice.deployment"
                    },
                    {
                      "literal": "large-discount"
                    }
                  ]
                },
                {
                  "op": "eq",
                  "args": [
                    {
                      "op": "lookup",
                      "table": "options",
                      "where": {
                        "id": {
                          "ref": "choice.deployment"
                        }
                      },
                      "column": "promoters"
                    },
                    {
                      "literal": 2
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "staffing-coverage",
        "requirement": "SUFFICIENCY",
        "kind": "predicate",
        "predicate": {
          "op": "gte",
          "args": [
            {
              "ref": "derived.insideStaff"
            },
            {
              "ref": "parameter.minimumInside"
            }
          ]
        }
      },
      {
        "id": "staffing-register",
        "requirement": "SUFFICIENCY",
        "kind": "predicate",
        "predicate": {
          "op": "lte",
          "args": [
            {
              "ref": "parameter.unavailableStaff"
            },
            {
              "ref": "parameter.qualifiedStaff"
            }
          ]
        }
      },
      {
        "id": "event-access",
        "requirement": "ACCESS",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "exists",
              "table": "access",
              "where": {
                "venueId": {
                  "ref": "parameter.venueId"
                },
                "eventId": {
                  "ref": "parameter.eventId"
                },
                "operatingDate": {
                  "ref": "parameter.operatingDate"
                },
                "activity": {
                  "literal": "street-promotion"
                }
              },
              "test": {
                "op": "and",
                "args": [
                  {
                    "ref": "row.granted"
                  },
                  {
                    "op": "ne",
                    "args": [
                      {
                        "ref": "row.source"
                      },
                      {
                        "literal": ""
                      }
                    ]
                  },
                  {
                    "op": "lte",
                    "args": [
                      {
                        "ref": "row.validFromMinute"
                      },
                      {
                        "ref": "parameter.promotionStartMinute"
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.validThroughMinute"
                      },
                      {
                        "ref": "parameter.contactEndMinute"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "spending-permission",
        "requirement": "ACCESS",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "exists",
              "table": "spending",
              "where": {
                "venueId": {
                  "ref": "parameter.venueId"
                },
                "operatingDate": {
                  "ref": "parameter.operatingDate"
                },
                "actorId": {
                  "ref": "parameter.actorId"
                }
              },
              "test": {
                "op": "and",
                "args": [
                  {
                    "op": "ne",
                    "args": [
                      {
                        "ref": "row.source"
                      },
                      {
                        "literal": ""
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.ceilingMinor"
                      },
                      {
                        "ref": "finance.expense"
                      }
                    ]
                  },
                  {
                    "op": "lte",
                    "args": [
                      {
                        "ref": "row.validFromMinute"
                      },
                      {
                        "ref": "parameter.dispatchMinute"
                      }
                    ]
                  },
                  {
                    "op": "gte",
                    "args": [
                      {
                        "ref": "row.validThroughMinute"
                      },
                      {
                        "ref": "parameter.staffReturnMinute"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "id": "dispatch-timing",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "gte",
                  "args": [
                    {
                      "ref": "parameter.dispatchMinute"
                    },
                    {
                      "ref": "parameter.reviewMinute"
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.dispatchMinute"
                    },
                    {
                      "ref": "parameter.promotionStartMinute"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "contact-window",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "and",
              "args": [
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.promotionStartMinute"
                    },
                    {
                      "ref": "parameter.eventExitMinute"
                    }
                  ]
                },
                {
                  "op": "lte",
                  "args": [
                    {
                      "ref": "parameter.eventExitMinute"
                    },
                    {
                      "ref": "parameter.contactEndMinute"
                    }
                  ]
                }
              ]
            }
          ]
        }
      },
      {
        "id": "useful-arrival",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "lte",
              "args": [
                {
                  "ref": "derived.customerArrivalMinute"
                },
                {
                  "ref": "parameter.latestArrivalMinute"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "staff-return",
        "requirement": "TIME",
        "kind": "predicate",
        "predicate": {
          "op": "or",
          "args": [
            {
              "op": "eq",
              "args": [
                {
                  "ref": "choice.deployment"
                },
                {
                  "literal": "hold"
                }
              ]
            },
            {
              "op": "gte",
              "args": [
                {
                  "ref": "parameter.staffReturnMinute"
                },
                {
                  "ref": "parameter.contactEndMinute"
                }
              ]
            }
          ]
        }
      },
      {
        "id": "expense-limit",
        "requirement": "COST",
        "kind": "predicate",
        "predicate": {
          "op": "lte",
          "args": [
            {
              "ref": "finance.expense"
            },
            {
              "ref": "parameter.expenseLimitMinor"
            }
          ]
        }
      }
    ],
    "finance": {
      "mode": "expense",
      "charges": [
        {
          "id": "complete-deployment-charge",
          "amount": {
            "op": "lookup",
            "table": "options",
            "where": {
              "id": {
                "ref": "choice.deployment"
              }
            },
            "column": "expenseMinor"
          }
        }
      ],
      "holds": []
    },
    "preference": {
      "mode": "feasibility-only"
    },
    "labels": {
      "plan": "Complete deployment",
      "expense": "Incremental deployment expense",
      "choice.deployment": "Deployment",
      "derived.promoters": "People outside",
      "derived.insideStaff": "Qualified staff remaining inside",
      "derived.customerArrivalMinute": "Conditional guest arrival minute",
      "constraint.published-option-structure": "Use one of the four complete deployment structures",
      "constraint.staffing-coverage": "Keep the required qualified staffing inside throughout the absence",
      "constraint.staffing-register": "Do not mark more qualified staff unavailable than are recorded",
      "constraint.event-access": "Have current recorded access for this event, date and promotion window",
      "constraint.spending-permission": "Have a sourced spending delegation covering Sam, this evening and the complete charge",
      "constraint.dispatch-timing": "Allow review, dispatch and the declared promotion start in that order",
      "constraint.contact-window": "Reach event departures before the useful contact window closes",
      "constraint.useful-arrival": "Leave enough journey time for interested additional guests to arrive usefully",
      "constraint.staff-return": "Keep the staff absence covered through the contact window",
      "constraint.expense-limit": "Keep the complete incremental deployment expense within the limit"
    },
    "metadata": {
      "catalog": {
        "domain": {
          "id": "venue-operations",
          "label": "Venue operations"
        },
        "useCase": {
          "id": "deploy-street-team",
          "label": "Review a street-team deployment"
        }
      },
      "decisionPresentation": {
        "format": "decision-presentation/1",
        "title": "Tonight\u2019s available deployments",
        "question": "Which deployments meet the recorded operating requirements?",
        "priorityLabel": "Feasibility only; Sam chooses among the passing deployments.",
        "moneyFormat": {
          "currency": "USD",
          "divisor": 100
        },
        "columns": [
          {
            "id": "deployment",
            "source": "choice:deployment",
            "label": "Deployment",
            "valueLabels": {
              "hold": "Make no further push",
              "small-standard": "One-person standard push",
              "large-standard": "Two-person standard push",
              "large-discount": "Two-person discount push"
            }
          },
          {
            "id": "status",
            "source": "status"
          },
          {
            "id": "inside",
            "source": {
              "kind": "derived",
              "id": "insideStaff"
            },
            "label": "Qualified staff inside",
            "format": {
              "kind": "number"
            }
          },
          {
            "id": "expense",
            "source": "expense",
            "label": "Incremental expense"
          },
          {
            "id": "blockers",
            "source": "blockers"
          }
        ]
      }
    }
  },
  "case": {
    "id": "street-team-friday",
    "parameters": {
      "venueId": "VENUE-SAM",
      "eventId": "EVENT-1120",
      "operatingDate": "2026-11-20",
      "actorId": "Sam",
      "qualifiedStaff": 7,
      "unavailableStaff": 0,
      "minimumInside": 4,
      "reviewMinute": 1170,
      "dispatchMinute": 1185,
      "promotionStartMinute": 1200,
      "eventExitMinute": 1215,
      "contactEndMinute": 1245,
      "staffReturnMinute": 1260,
      "customerJourneyMinutes": 30,
      "latestArrivalMinute": 1275,
      "expenseLimitMinor": 40000
    },
    "tables": {
      "options": [
        {
          "id": "hold",
          "label": "Make no further push",
          "promoters": 0,
          "expenseMinor": 0
        },
        {
          "id": "small-standard",
          "label": "One-person standard push",
          "promoters": 1,
          "expenseMinor": 20000
        },
